constType:
∀ (p : ℕ) [inst : Fact (Nat.Prime p)] (c : FormalizedSparse.LiftedPAdicHahnSeries p)
  {x : FormalizedSparse.LiftedPAdicHahnSeries p},
  x ∈ {x | FormalizedSparse.IsNullSeries x} → c • x ∈ {x | FormalizedSparse.IsNullSeries x}

∀ {toFun : ℕ+ → ℕ} {fin_supp : (Function.support toFun).Finite} {toFun_1 : ℕ+ → ℕ}
  {fin_supp_1 : (Function.support toFun_1).Finite},
  { toFun := toFun, fin_supp := fin_supp } = { toFun := toFun_1, fin_supp := fin_supp_1 } → toFun = toFun_1

∀ (p : ℕ) [inst : Fact (Nat.Prime p)] {a b : FormalizedSparse.LiftedPAdicHahnSeries p},
  a ∈ {x | FormalizedSparse.IsNullSeries x} →
    b ∈ {x | FormalizedSparse.IsNullSeries x} → a + b ∈ {x | FormalizedSparse.IsNullSeries x}

∀ (p : ℕ) [inst : Fact (Nat.Prime p)],
  FormalizedSparse.NullSeriesIdeal p =
    { carrier := {x | FormalizedSparse.IsNullSeries x}, add_mem' := ⋯, zero_mem' := ⋯, smul_mem' := ⋯ }

∀ (x : List ℕ),
  FormalizedSparse.Sparse.DigitSeries.ofCoeffs x =
    match x with
    | [] => { toFun := 0, fin_supp := FormalizedSparse.Sparse.DigitSeries.ofCoeffs._proof_3 }
    | a :: L =>
      let f := FormalizedSparse.Sparse.DigitSeries.ofCoeffs L;
      { toFun := Function.update (⇑f) L.length.succPNat a, fin_supp := ⋯ }

∀ (p : ℕ) [inst : Fact (Nat.Prime p)],
  closure (integralClosure ℚᵘⁿ_[p] 𝕃_[p]).carrier =
    closure {f | ∃ f', IsAlgebraic 𝔽ᵃ_[p] f' ∧ ↑(Exists.choose ⋯) = f'.coeff}

∀ {p : ℕ} [inst : Fact (Nat.Prime p)] (s : ℚ → 𝔽ᵃ_[p]) (hspwo : (Function.support s).IsPWO),
  FormalizedSparse.LiftedPAdicHahnSeries.fromCoeff s hspwo =
    { coeff := fun n => (WittVector.teichmuller p) (s n), isPWO_support' := ⋯ }

∀ (p : ℕ) [inst : Fact (Nat.Prime p)] (T : ℕ) [inst_1 : NeZero T]
  (c : FormalizedSparse.TScaled.TLiftedPAdicHahnSeries p T) {x : FormalizedSparse.TScaled.TLiftedPAdicHahnSeries p T},
  x ∈ {x | FormalizedSparse.TScaled.IsTNullSeries p T x} → c • x ∈ {x | FormalizedSparse.TScaled.IsTNullSeries p T x}

∀ (a : ℕ) (L : List ℕ),
  FormalizedSparse.Sparse.DigitSeries.ofCoeffs (a :: L) =
    { toFun := Function.update (⇑(FormalizedSparse.Sparse.DigitSeries.ofCoeffs L)) L.length.succPNat a, fin_supp := ⋯ }

∀ {p : ℕ} [inst : Fact (Nat.Prime p)] {S : Set FormalizedSparse.Sparse.DigitSeries} {hS : ∀ f ∈ S, f.IsP p} {c n : ℕ+}
  (hSparse : FormalizedSparse.Sparse.IsCNSparse p c n S hS) (d : ↑S),
  FormalizedSparse.Sparse.φ₀ hSparse d = Nat.card ↑(⋯.choose ⁻¹' {d})
